const dayInMilliseconds = 1000 * 60 * 60 * 24
const relativeFormatter = new Intl.RelativeTimeFormat("en", { numeric: "auto" })
const formats = {
  time: { hour: "numeric", minute: "2-digit" },
  date: { month: "short", day: "numeric" },
  "date-with-year": { year: "numeric", month: "short", day: "numeric" },
  "long-date": { weekday: "long", month: "long", day: "numeric" },
  datetime: { year: "numeric", month: "short", day: "numeric", hour: "numeric", minute: "2-digit" }
}
const formatters = new Map()

export function formatLocalTime(date, format = "relative", now = new Date()) {
  if (format === "relative") {
    const days = localDayNumber(date) - localDayNumber(now)

    if (days === 0) {
      return formatLocalTime(date, "time", now)
    } else if (days >= -6) {
      return relativeFormatter.format(days, "day")
    } else {
      return formatLocalTime(date, date.getFullYear() === now.getFullYear() ? "date" : "date-with-year", now)
    }
  } else {
    if (!formatters.has(format)) {
      formatters.set(format, new Intl.DateTimeFormat("en-US", formats[format] || formats.datetime))
    }

    return formatters.get(format).format(date)
  }
}

// Compare local calendar dates, not elapsed hours: DST days can be 23 or 25 hours.
function localDayNumber(date) {
  return Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()) / dayInMilliseconds
}
EOF
